WHERE toLower(pub.name) CONTAINS 'sporting news'
  AND (
    toLower(a.published_on) CONTAINS '2023-11-06'
    OR toLower(a.published_on) CONTAINS '2023-11-11'
    OR toLower(a.published_on) CONTAINS 'november 6'
    OR toLower(a.published_on) CONTAINS 'november 11'
