OPTIONAL MATCH (a)-[:MENTIONS]->(e:__Entity__)
OPTIONAL MATCH (e)-[r]-(related:__Entity__)
RETURN a.name AS article, a.published_on AS published_on,
       collect(DISTINCT e.name) AS entities,
       collect(DISTINCT CASE WHEN r IS NOT NULL
         THEN {entity: e.name, relationship: type(r), related: related.name}
