Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p:Publisher),
      (a)-[:MENTIONS]->(e:Person)
WHERE (
  toLower(p.name) CONTAINS 'the independent'
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the independent')
  OR toLower(p.name) CONTAINS 'the age'
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the age')
  OR toLower(p.name) CONTAINS 'cbssports.com'
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'cbssports.com')
)
AND (
  toLower(e.name) CONTAINS 'taylor swift'
  OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'taylor swift')
  OR toLower(e.name) CONTAINS 'travis kelce'
  OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'travis kelce')
)
RETURN DISTINCT a.name AS article, a.published_on AS published_on, p.name AS publisher, p.section AS section, e.name AS connected_person
ORDER BY CASE WHEN toLower(coalesce(a.name, '')) CONTAINS 'tour'
                  AND (toLower(coalesce(a.name, '')) CONTAINS 'schedule'
                       OR toLower(coalesce(a.name, '')) CONTAINS 'cancel')
             THEN 0 ELSE 1 END
LIMIT 10
